def valid_ipv4(ip):
    """
    Validate if a given string represents a valid IPv4 address.

    Args:
    ip (str): The IP address to validate.

    Returns:
    bool: True if the IP address is valid, False otherwise.
    """
    parts = ip.split(".")

    # An IPv4 address should have exactly 4 parts
    if len(parts) != 4:
        return False

    for part in parts:
        # Each part should be a digit
        if not part.isdigit():
            return False

        # Convert the part to an integer
        num = int(part)

        # The number should be between 0 and 255
        if num < 0 or num > 255:
            return False

        # The number should not have leading zeros
        if len(part) > 1 and part[0] == '0':
            return False

    return True
